def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    # Ensure we only process up to n+1 terms or the length of coeffs, whichever is smaller
    length = min(n + 1, len(coeffs))
    for i in range(length):
        coeff = coeffs[i]
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign and absolute coefficient
        sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)

        # Build coefficient part
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_str = ''
            else:
                coeff_str = str(abs_coeff)

        # Build variable part
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'

        term = coeff_str + var_str

        # Append sign appropriately
        if not terms:
            # First term: sign only if negative
            if sign == '-':
                terms.append('-' + term)
            else:
                terms.append(term)
        else:
            terms.append(sign + term)

    if not terms:
        return '0'
    return ''.join(terms)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.

    Args:
        inorder (str): The inorder traversal of the binary tree.
        postorder (str): The postorder traversal of the binary tree.

    Returns:
        str: The preorder traversal of the binary tree.
    """
    # Helper recursive function
    def build_pre(in_in: str, post_in: str) -> str:
        if not in_in:
            return ''
        if len(in_in) != len(post_in):
            raise ValueError("Inorder and postorder lengths do not match.")
        root = post_in[-1]
        try:
            idx = in_in.index(root)
        except ValueError:
            raise ValueError(f"Root '{root}' not found in inorder traversal.")
        left_in = in_in[:idx]
        right_in = in_in[idx + 1 :]
        left_post = post_in[:len(left_in)]
        right_post = post_in[len(left_in) : -1]
        return root + build_pre(left_in, left_post) + build_pre(right_in, right_post)

    # Handle empty input
    if not inorder and not postorder:
        return ''
    if not inorder or not postorder:
        return ''
    try:
        return build_pre(inorder, postorder)
    except Exception:
        # In case of invalid input, return empty string
        return ''

def generate_numbers(n, rules) -> int:
    # Validate
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule)==2):
            raise ValueError("Each rule must be a tuple of two elements")
        x,y = rule
        if not (isinstance(x,int) and isinstance(y,int)):
            raise ValueError("Rule elements must be integers")
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("Rule digits must be between 0 and 9")
    # BFS
    from collections import deque
    visited = set()
    queue = deque()
    visited.add(n)
    queue.append(n)
    while queue:
        current = queue.popleft()
        s = str(current)
        for i,ch in enumerate(s):
            for x,y in rules:
                if ch == str(x):
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If the input is not a list of tuples of appropriate types.
        ValueError: If any tuple does not contain exactly three elements.
    """
    # Basic validation
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise TypeError(f"Element at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Tuple at index {idx} does not contain exactly three elements")
        student_number, total_score, chinese_score = item
        if not isinstance(student_number, int):
            raise TypeError(f"Student number at index {idx} is not an integer")
        if not isinstance(total_score, (int, float)):
            raise TypeError(f"Total score at index {idx} is not a number")
        if not isinstance(chinese_score, (int, float)):
            raise TypeError(f"Chinese score at index {idx} is not a number")

    # Perform sorting
    return sorted(
        student_scores,
        key=lambda x: (-x[1], -x[2], x[0])
    )
